<!-- 文件作用：公开俱乐部装修主页、认证成员与加入规则，同时保留负责人审核和团队订单协作。 -->
<template><AppShell immersive active="index"><view v-if="error" class="error-box club-error" @click="load">{{ error }} · 点击重试</view><view v-if="loading&&!club" class="loading-line">正在读取俱乐部…</view><template v-if="club"><view class="club-cover"><image :src="assetUrl(cover)" mode="aspectFill"/><view class="cover-shade"/><view class="club-toolbar" :style="nativeHeader"><button @click="back"><Icon name="back" :size="25"/></button><view><button open-type="share" @click="sharePage"><Icon name="upload" :size="23"/></button><button v-if="canManage" @click="go('/pages/club-edit/index?id='+id)">装修</button></view></view></view><view class="club-content"><view class="club-identity"><view class="club-crest"><Icon name="club" :size="38"/></view><view><view class="club-name-row"><text class="club-title">{{ club.name }}</text><view v-if="club.verified&&club.status==='active'" class="club-verified"><Icon name="shield" :size="13"/>平台认证</view></view><text class="club-tagline">{{ club.owner_name }} 主理 · {{ club.status==='active'?'热爱游戏，认真履约':statusLabel(club.status) }}</text></view></view><view class="club-stats"><view><text>{{ club.member_count||0 }}</text><text>认证成员</text></view><view><text>{{ club.game_ids?.length||0 }}</text><text>覆盖游戏</text></view></view><view class="game-tags"><text v-for="gameId in club.game_ids" :key="gameId">{{ gameName(gameId) }}</text></view><button class="requirements-card" @click="rulesOpen=true"><Icon name="shield" :size="26"/><view><text>加入门槛：{{ club.assessment?'需考核':'自由申请' }}<text v-if="club.deposit_cents"> · 押金规则 ¥{{ money(club.deposit_cents) }}</text></text><text>平台暂不代收押金。</text></view><view class="view-rules">查看规则 <Icon name="arrow" :size="13"/></view></button><view class="club-actions"><button v-if="canManage" class="btn" @click="selectTab('manage')">成员管理</button><button v-else-if="membership?.status==='active'" class="btn-secondary" :disabled="busy" @click="leave">退出俱乐部</button><button v-else class="btn" :disabled="busy||club.status!=='active'" @click="openJoin">{{ membership?.status==='pending'?'查看申请 / 更新确认':'申请加入' }}</button><button class="btn-secondary share-action" open-type="share" @click="sharePage"><Icon name="upload" :size="18"/>分享主页</button></view><view class="club-tabs"><button :class="{active:tab==='info'}" @click="selectTab('info')">详细信息</button><button :class="{active:tab==='members'}" @click="selectTab('members')">成员列表</button><button v-if="canManage" :class="{active:tab==='manage'}" @click="selectTab('manage')">审核管理</button><button v-if="canManage" :class="{active:tab==='orders'}" @click="selectTab('orders')">团队订单</button></view>
<template v-if="tab==='info'"><view class="club-details"><text class="detail-title">关于我们</text><text class="detail-text">{{ club.description }}</text><template v-for="(block,index) in club.detail_blocks||[]" :key="index"><text v-if="block.type==='text'" class="detail-text">{{ block.text }}</text><image v-else-if="block.type==='image'" :src="assetUrl(block.image_url)" mode="widthFix" class="detail-image" @click="previewImage(block.image_url)"/></template></view><template v-if="services.length"><text class="detail-title services-heading">俱乐部服务</text><view class="card-grid"><ServiceCard v-for="service in services" :key="service.id" :service="service"/></view></template></template>
<template v-else-if="tab==='members'"><EmptyState v-if="!certifiedMembers.length" title="暂未展示认证成员" detail="通过挂靠审核的有效成员会展示在这里。" icon="club"/><view v-for="member in certifiedMembers" :key="member.user_id" class="member-card" @click="go('/pages/player/index?id='+member.user_id)"><image v-if="member.avatar" :src="assetUrl(member.avatar)" mode="aspectFill"/><view v-else class="member-avatar"><Icon name="user" :size="24"/></view><view><text>{{ member.nickname }}</text><view class="member-cert"><Icon name="shield" :size="11"/>俱乐部认证成员</view></view><Icon name="arrow" :size="16"/></view></template>
<template v-else-if="tab==='manage'&&canManage"><view class="notice mb">认证须审核真实申请和考核。押金状态未经平台核验，不代表已支付。</view><EmptyState v-if="!members.length" title="暂无成员申请" detail="成员可以通过公开主页了解规则并申请加入。"/><view v-for="member in members" :key="member.user_id" class="manage-member panel"><view class="row between"><text>{{ member.nickname }}</text><text class="pill">{{ member.status==='active'?'已认证':member.status==='pending'?'待审核':member.status==='left'?'已退出':'未通过' }}</text></view><text v-if="member.application_note" class="application-note">申请说明：{{ member.application_note }}</text><text class="hint">{{ time(member.created_at) }}</text><text v-if="member.applied_deposit_cents" class="hint">申请押金规则 ¥{{ money(member.applied_deposit_cents) }} · 未经平台核验</text><text v-if="member.applied_assessment" class="hint">考核要求：{{ member.applied_assessment }}</text><view v-if="member.user_id!==club.owner_id" class="member-actions"><button v-if="member.status==='pending'" class="btn btn-small" :disabled="busy" @click="prepareReview(member,'active')">审核通过</button><button v-if="['pending','active'].includes(member.status)" class="btn-secondary btn-small" :disabled="busy" @click="prepareReview(member,'rejected')">{{ member.status==='active'?'移除成员':'拒绝申请' }}</button></view></view></template>
<template v-else-if="tab==='orders'&&canManage"><view class="notice mb">进入团队订单聊天室，协助双方履约与处理争议。</view><view v-if="ordersError" class="error-box" @click="loadOrders()">{{ ordersError }} · 点击重试</view><EmptyState v-else-if="!orders.length&&!ordersLoading" title="暂无团队订单" detail="有效挂靠产生的订单会展示在这里。"/><view v-for="order in orders" :key="order.id" class="team-order panel" @click="go('/pages/order/index?id='+order.id)"><view class="row between"><text>{{ order.title }}</text><text class="accent">¥{{ money(order.amount_cents) }}</text></view><text class="hint">{{ order.buyer_name }} → {{ order.provider_name||'等待接单' }}</text><view class="row between"><text class="pill">{{ statusLabel(order.status) }}</text><text class="text-btn">进入聊天室</text></view></view><button v-if="ordersMore" class="btn-secondary load-more" :disabled="ordersLoading" @click="loadOrders(true)">{{ ordersLoading?'正在加载…':'加载更多订单' }}</button></template>
<view class="club-note"><Icon name="info" :size="14"/>认证代表平台已审核，不承诺服务结果。</view></view></template>
<view v-if="rulesOpen||joining" class="club-mask" @click="closeJoin"><scroll-view scroll-y class="club-modal rules-modal" @click.stop><view class="modal-heading"><text>{{ joining?'申请加入':'加入规则' }}</text><button :disabled="busy" @click="closeJoin"><Icon name="close" :size="22"/></button></view><view class="rule-item"><text>押金规则</text><text>{{ club?.deposit_cents?'¥'+money(club.deposit_cents):'未设置押金门槛' }}</text><text class="hint">平台暂不代收或核验押金，不会将申请显示为已支付。</text></view><view class="rule-item"><text>考核要求</text><text class="rule-body">{{ club?.assessment||'提交申请后由俱乐部负责人审核。' }}</text></view><template v-if="joining"><textarea v-model="applicationNote" class="input" maxlength="500" placeholder="介绍你的游戏经验和加入意向（选填）"/><checkbox-group v-if="hasRequirements" @change="requirementsAccepted=$event.detail.value.includes('accepted')"><label class="rules-consent"><checkbox value="accepted" :checked="requirementsAccepted" :color="game.primary_color"/><text>我已阅读并同意以上加入门槛与规则。</text></label></checkbox-group><button class="btn" :disabled="busy" @click="submitJoin">{{ busy?'正在提交…':membership?.status==='pending'?'更新申请确认':'提交加入申请' }}</button></template></scroll-view></view>
<view v-if="reviewing" class="club-mask" @click="!busy&&(reviewing=null)"><view class="club-modal" @click.stop><text class="modal-title">{{ reviewStatus==='active'?'确认认证成员':'确认拒绝 / 移除' }}</text><text class="hint">{{ reviewing.nickname }}</text><text v-if="reviewing.applied_assessment" class="rule-body">申请时考核：{{ reviewing.applied_assessment }}</text><checkbox-group v-if="reviewStatus==='active'&&club.assessment" @change="assessmentPassed=$event.detail.value.includes('passed')"><label class="rules-consent"><checkbox value="passed" :checked="assessmentPassed" :color="game.primary_color"/><text>已完成并通过要求的考核</text></label></checkbox-group><textarea v-model="reviewNote" class="input" maxlength="500" placeholder="审核说明（选填，会保留记录）"/><view class="row"><button class="btn-secondary" :disabled="busy" @click="reviewing=null">取消</button><button class="btn" :disabled="busy" @click="submitReview">确认处理</button></view></view></view>
</AppShell></template>
<script setup>
import { ref, computed, onMounted } from 'vue'
import { onLoad, onShow, onHide, onShareAppMessage } from '@dcloudio/uni-app'
import AppShell from '../../components/AppShell.vue'
import Icon from '../../components/Icon.vue'
import EmptyState from '../../components/EmptyState.vue'
import ServiceCard from '../../components/ServiceCard.vue'
import { state, game, init, sessionRevision } from '../../lib/store'
import { api } from '../../lib/api'
import { requirePhone } from '../../lib/phone'
import { go,notify,time,money,statusLabel,assetUrl } from '../../lib/format'
const id=ref(''),club=ref(null),members=ref([]),membership=ref(null),services=ref([]),canManage=ref(false),tab=ref('info'),busy=ref(false),loading=ref(true),error=ref(''),nativeHeader=ref({})
const rulesOpen=ref(false),joining=ref(false),applicationNote=ref(''),requirementsAccepted=ref(false),reviewing=ref(null),reviewStatus=ref(''),reviewNote=ref(''),assessmentPassed=ref(false)
const orders=ref([]),ordersMore=ref(false),ordersLoading=ref(false),ordersError=ref('')
const cover=computed(()=>club.value?.cover_url||state.games.find(item=>item.id===club.value?.game_ids?.[0])?.cover_url||game.value.cover_url)
const hasRequirements=computed(()=>!!club.value?.deposit_cents||!!club.value?.assessment)
const certifiedMembers=computed(()=>members.value.filter(member=>member.certified===true||member.status==='active'))
let version=0,ordersVersion=0
/** 读取公开展示及服务端计算的管理权限，不从客户端自行授予权限。 */
async function load(){if(!id.value)return;const current=++version;loading.value=true;try{await init();if(current!==version)return;const revision=sessionRevision(),result=await api('/clubs/'+encodeURIComponent(id.value));if(current!==version||revision!==sessionRevision())return;club.value=result.club;members.value=result.members||[];services.value=(result.services||[]).filter(service=>service.status==='active');membership.value=result.my_membership;canManage.value=!!result.can_manage;if(!canManage.value){orders.value=[];ordersMore.value=false;if(['manage','orders'].includes(tab.value))tab.value='info'}error.value='';if(tab.value==='orders')loadOrders()}catch(err){if(current===version)error.value=err.message}finally{if(current===version)loading.value=false}}
/** 切换公开内容或权限内管理页，团队订单独立分页。 */
function selectTab(value){tab.value=value;if(value==='orders'&&canManage.value)loadOrders()}
/** 读取当前负责人有权协作的团队订单，忽略旧身份响应。 */
async function loadOrders(append=false){const adding=append===true;if(ordersLoading.value||!canManage.value)return;const current=++ordersVersion,revision=sessionRevision();ordersLoading.value=true;ordersError.value='';try{const result=await api('/clubs/'+id.value+'/orders?limit=20&offset='+(adding?orders.value.length:0));if(current!==ordersVersion||revision!==sessionRevision())return;orders.value=adding?[...orders.value,...result]:result;ordersMore.value=result.length===20}catch(err){if(current===ordersVersion&&revision===sessionRevision())ordersError.value=err.message}finally{if(current===ordersVersion)ordersLoading.value=false}}
/** 显示俱乐部覆盖游戏的简称。 */
function gameName(gameId){return state.games.find(item=>item.id===gameId)?.short_name||gameId}
/** 申请前先登录，规则确认始终由用户主动勾选。 */
function openJoin(){if(!state.user)return go('/pages/login/index?next='+encodeURIComponent('/pages/club/index?id='+id.value));joining.value=true;rulesOpen.value=false;requirementsAccepted.value=false;applicationNote.value=membership.value?.application_note||''}
/** 关闭加入或规则面板，不发送申请。 */
function closeJoin(){if(!busy.value){rulesOpen.value=false;joining.value=false}}
/** 提交真实加入意向及门槛确认，手机号验证由统一组件处理。 */
async function submitJoin(){if(busy.value)return;if(hasRequirements.value&&!requirementsAccepted.value)return notify('请先阅读并同意加入规则');const revision=sessionRevision();busy.value=true;try{if(!(await requirePhone())||revision!==sessionRevision())return;await api('/clubs/'+id.value+'/join','POST',{application_note:applicationNote.value.trim(),requirements_accepted:requirementsAccepted.value});if(revision!==sessionRevision())return;joining.value=false;await load();notify('加入申请已提交，等待审核')}catch(err){if(revision===sessionRevision())notify(err)}finally{busy.value=false}}
/** 退出前明确提醒认证影响，原订单沟通与证据不被删除。 */
function leave(){if(busy.value)return;const revision=sessionRevision();uni.showModal({title:'退出俱乐部',content:'退出后新服务不能使用该俱乐部认证，已有订单和证据仍会保留。',success:async result=>{if(!result.confirm||busy.value||revision!==sessionRevision())return;busy.value=true;try{await api('/clubs/'+id.value+'/leave','POST',{});if(revision===sessionRevision()){await load();notify('已退出俱乐部')}}catch(err){if(revision===sessionRevision())notify(err)}finally{busy.value=false}}})}
/** 打开有明确考核确认与审核备注的成员处理表单。 */
function prepareReview(member,status){reviewing.value=member;reviewStatus.value=status;reviewNote.value='';assessmentPassed.value=false}
/** 提交审核结果，有考核时必须明确确认，规则变化冲突由服务端拒绝。 */
async function submitReview(){if(busy.value||!reviewing.value)return;if(reviewStatus.value==='active'&&club.value.assessment&&!assessmentPassed.value)return notify('请确认成员已通过考核');const revision=sessionRevision();busy.value=true;try{await api('/clubs/'+id.value+'/members/'+reviewing.value.user_id,'POST',{status:reviewStatus.value,assessment_passed:assessmentPassed.value,review_note:reviewNote.value.trim()});if(revision!==sessionRevision())return;reviewing.value=null;await load();notify('成员审核已保存')}catch(err){if(revision===sessionRevision())notify(err)}finally{busy.value=false}}
/** 使用原生预览展示已托管的装修图片。 */
function previewImage(url){uni.previewImage({current:assetUrl(url),urls:(club.value.detail_blocks||[]).filter(block=>block.type==='image').map(block=>assetUrl(block.image_url))})}
/** 返回浏览来源或公开俱乐部列表。 */
function back(){if(getCurrentPages().length>1)uni.navigateBack();else go('/pages/clubs/index')}
/** 网页复制链接，微信交给分享按钮与分享生命周期。 */
function sharePage(){
  // #ifdef H5
  uni.setClipboardData({data:location.origin+'/#/pages/club/index?id='+encodeURIComponent(id.value),success:()=>notify('主页链接已复制')})
  // #endif
}
/** 顶部操作栏避让微信状态栏和胶囊。 */
function fitHeader(){
  // #ifdef MP-WEIXIN
  const capsule=uni.getMenuButtonBoundingClientRect(),info=uni.getWindowInfo();if(capsule?.width)nativeHeader.value={paddingTop:capsule.top+'px',paddingRight:info.windowWidth-capsule.left+12+'px'}
  // #endif
}
/** 校验路由含俱乐部编号后再加载。 */
function applyRoute(options){id.value=options.id||'';if(id.value)load();else{loading.value=false;error.value='俱乐部不存在'}}
onLoad(applyRoute)
onShow(()=>{if(id.value)load()})
onHide(()=>{version++;ordersVersion++;ordersLoading.value=false;orders.value=[];ordersMore.value=false;canManage.value=false;reviewing.value=null;joining.value=false;membership.value=null})
onMounted(fitHeader)
onShareAppMessage(()=>({title:(club.value?.name||'俱乐部')+' · 集结',path:'/pages/club/index?id='+encodeURIComponent(id.value),imageUrl:assetUrl(cover.value)}))
</script>
<style scoped>
